#include<bits/stdc++.h>

using namespace std;

int n;
vector<int> a;
vector<vector<int>> g;

int cnt=0;
set<int> s;
vector<int> ans;

void dfs(int v,int pv){
  int del=0;
  if(s.find(a[v])!=s.end()){del=1;}
  else{s.insert(a[v]);}
  cnt+=del;
  if(cnt>0){ans[v]=1;}
  else{ans[v]=0;}
  for(auto &nx : g[v]){
    if(nx==pv){continue;}
    dfs(nx,v);
  }
  cnt-=del;
  if(del==0){
    s.erase(a[v]);
  }
}

int main(){
  cin >> n;
  a.resize(n);
  for(auto &nx : a){cin >> nx;}
  g.resize(n);
  for(int i=1;i<n;i++){
    int u,v;
    cin >> u >> v;
    u--; v--;
    g[u].push_back(v);
    g[v].push_back(u);
  }
  ans.resize(n);
  dfs(0,-1);
  for(auto &nx : ans){
    if(nx){cout << "Yes\n";}
    else{cout << "No\n";}
  }
  return 0;
}
